def transform(grid):
    out = [row[:] for row in grid]
    R, C = len(grid), len(grid[0])
    seen = set()
    for r in range(R):
        for c in range(C):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            comp = []
            seen.add((r, c))
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx, ny = x+dx, y+dy
                    if 0 <= nx < R and 0 <= ny < C and grid[nx][ny] == 5 and (nx,ny) not in seen:
                        seen.add((nx,ny))
                        stack.append((nx,ny))
            rs = [x for x, _ in comp]
            cs = [y for _, y in comp]
            top, bottom, left, right = min(rs), max(rs), min(cs), max(cs)
            cells = set(comp)
            # Detect a rectangular frame with a single missing cell in its top edge.
            gaps = [y for y in range(left, right+1) if (top,y) not in cells]
            if (len(gaps) == 1 and
                all((x,left) in cells and (x,right) in cells for x in range(top,bottom+1)) and
                all((bottom,y) in cells for y in range(left,right+1))):
                gap = gaps[0]
                for x in range(top+1, bottom):
                    for y in range(left+1, right):
                        if (x,y) not in cells:
                            out[x][y] = 2
                out[top][gap] = 2
                if top > 0:
                    for y in range(gap+1):
                        out[top-1][y] = 2
    return out
